 // Object 	/// <summary> Watched File path and last modified date in ms  </summary>	public struct FileData {		/// <summary> File path </summary>		public string Fpath;		/// <summary> Last modified file date </summary>		public int LastModDate { get; set; }		/// <summary> Watched File path and last modified date in ms  </summary>		public FileData(string fpath) : this() {			Fpath = fpath;			LastModDate = File.GetLastWriteTime(fpath).Millisecond;		}	}	//New event Args	/// <summary> File data event arguments </summary>	public class FileDataEventArgs:EventArgs {		/// <summary> File path </summary>		public string Fpath { get; set; }		/// <summary> File data event arguments </summary>		public FileDataEventArgs(string fpath) {			Fpath = fpath;		}	}  // Declare a delegate for the parameters:	/// <summary> New Event Handler </summary>	public delegate void FileWatcherEventHandler(object o, FileDataEventArgs:EventArgs e);	/// <summary> This callback is called when file modification is detected in watched file. </summary>	public event FileWatcherEventHandler FileChanged;// Fire eventFileChanged?.Invoke(this, new FileDataEventArgs(item.Fpath));//OR//Declare (inside in ListBox Control Extension or Control where ListBox is present)        // Custom EventArgs        public class SelectItemsEventArgs {            public SelectItemsEventArgs(List<string> itemsList) { Items = itemsList; }            public List<string> Items { get; } // readonly        }        // Declare the delegate (if using non-generic pattern).        public delegate void SelectItemsEventHandler(object sender, SelectItemsEventArgs e);        // Declare the event.        public event SelectItemsEventHandler OnListItemSelected;//Register (somewhere in form or control, where you wish to get response each time when an item(s) is selected)OnListItemSelected += IUGlobal.IScene.OnListItemSelected;//Fire (inside in ListBox Control Extension or Control where ListBox is present)        private void OnSelectionChanged(object sender, SelectItemsEventArgs e) {            var listBox = (ListBox)sender;            var selectedItems = listBox.SelectedItems.Cast<string>().ToList();            //Console.WriteLine("selectedItems:{0}", selectedItems.Count);            listBox.Invalidate();            OnListItemSelected?.Invoke(this, new SelectItemsEventArgs(selectedItems));        }//Catch  (somewhere in form or control, where you wish to get response each time when an item(s) is selected)        internal void OnListItemSelected(object sender, SpriteListBox.SelectItemsEventArgs e) {            Console.WriteLine(Name + "OnListItemSelected:{0}", e.Items);        }